1351					console.log("[mcp-app] tools/call", name, args);
1352					setLastResult((last) => ({
1353						isError: false,
1354						seq: (last?.seq ?? 0) + 1,
1355					}));
1356				}
1357				return;
1358			}
1359			try {
1360				const result = await app.callServerTool({
1361					name,
1362					arguments: args,
1363					...(name === "resolve_lobu_approval" && approvalCapability
1364						? { _meta: { "lobu/approval-capability": approvalCapability } }
1365						: {}),
1366				});
1367				if (isStructuredObject(result.structuredContent)) {
1368					const nextData = result.structuredContent as T;
1369					const nextSnapshotCapability = snapshotCapabilityFromMeta(result._meta);
1370					resetResultViewState();
1371					pendingCompatibilityMetadata.current = null;
1372					resultExplicitlyCleared.current = false;
1373					hasAuthoritativeResultAbsence.current = false;
1374					supersededHostIdentity.current =
1375						toolCallId.current === null || toolCallName.current === null
1376							? null
1377							: hostIdentityKey(toolCallId.current, toolCallName.current);
1378					hasDetachedAppResult.current = true;
1379					toolCallId.current = null;
1380					toolCallName.current = name;
1381					setToolName(name);
1382					snapshotCapability.current = nextSnapshotCapability ?? null;
1383					resultCapabilityIdentity.current =
1384						typeof nextSnapshotCapability === "string"
1385							? nextSnapshotCapability
1386							: null;
1387					if (typeof nextSnapshotCapability === "string") {
1388						// This iframe made the call and received the complete replacement
1389						// result, so there is no historical view state to hydrate before its
1390						// first local edit is saved.
1391						snapshotRestoreCompleted.current.add(
1392							JSON.stringify([null, name, nextSnapshotCapability]),
1393						);
1394					}
1395					hasLiveToolOutput.current = true;
1396					hasAuthoritativeResultData.current = true;
1397					hasCurrentLifetimeToolResult.current = true;
