1405					persistOpenAiData(
1406						openAiCompatTargets(),
1407						nextData,
1408						nextSnapshotCapability ?? null,
1409					);
1410				}
1411				if (name === "resolve_lobu_approval" && result.isError !== true) {
1412					setApprovalCapability(null);
