1414				setLastResult((last) => ({
1415					isError: result.isError === true,
1416					seq: (last?.seq ?? 0) + 1,
1417				}));
1418			} catch {
1419				setLastResult((last) => ({
1420					isError: true,
1421					seq: (last?.seq ?? 0) + 1,
1422				}));
1423			}
1424		};
1425	
1426		const openLink = async (href: string) => {
1427			if (!isExternalHttpUrl(href)) {
1428				console.warn("[mcp-app] refused non-HTTP external link");
