 10	const logger = createLogger("mcp-app-result-snapshots");
 11	
 12	const MCP_APP_RESULT_MAX_BYTES = 512 * 1024;
 13	const MCP_APP_RESULT_RETENTION_DAYS = 30;
 14	const MCP_APP_RESULT_CONVERSATION_CAP = 50;
 15	const TOOL_CALL_ID_MAX_LENGTH = 512;
 16	const TOOL_NAME_MAX_LENGTH = 120;
 17	const VIEW_STATE_MAX_KEYS = 100;
 18	const VIEW_STATE_KEY_MAX_LENGTH = 120;
 19	const VIEW_STATE_STRING_MAX_LENGTH = 500;
 20	const VIEW_STATE_MAX_BYTES = 8 * 1024;
 21	
 22	type UnknownRecord = Record<string, unknown>;
 23	type McpAppViewState = Record<string, boolean | number | string>;
 24	
 25	interface SnapshotPayload {
 26		version: 1;
 27		toolName: string;
 28		data: UnknownRecord;
 29		viewState: McpAppViewState;
 30		/** SHA-256 of the single-use capability; retained after binding for idempotency. */
 31		bindingKey?: string;
 32	}
 33	
 34	interface SnapshotIdentity {
 35		organizationId: string;
 36		clientId: string;
 37		userId: string;
 38		conversationKey: string;
 39		toolCallKey: string;
 40	}
 41	
 42	interface SnapshotRow {
 43		body: string;
 44		tool_name: string;
 45	}
 46	
 47	interface SnapshotLookupRow extends SnapshotRow {
 48		tool_call_key: string;
 49	}
 50	
 51	function isRecord(value: unknown): value is UnknownRecord {
 52		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
 53	}
 54	
 55	export function normalizeMcpAppToolCallId(value: unknown): string | null {
 56		if (typeof value !== "string" && typeof value !== "number") return null;
 57		if (typeof value === "number" && !Number.isFinite(value)) return null;
 58		const normalized = String(value).trim();
 59		return normalized && normalized.length <= TOOL_CALL_ID_MAX_LENGTH
 60			? normalized
 61			: null;
 62	}
 63	
 64	function hashIdentity(value: string): string {
 65		return createHash("sha256").update(value, "utf8").digest("hex");
 66	}
 67	
 68	function snapshotIdentity(
 69		ctx: ToolContext,
 70		toolCallId: unknown,
 71	): SnapshotIdentity | null {
 72		const normalizedToolCallId = normalizeMcpAppToolCallId(toolCallId);
 73		const conversationId = ctx.mcpConversationId?.trim();
 74		if (
 75			ctx.mcpAppsSupported !== true ||
 76			ctx.tokenType !== "oauth" ||
 77			!ctx.clientId ||
 78			!ctx.userId ||
 79			!conversationId ||
 80			conversationId.length > 512 ||
 81			!normalizedToolCallId
 82		) {
 83			return null;
 84		}
 85		return {
 86			organizationId: ctx.organizationId,
 87			clientId: ctx.clientId,
 88			userId: ctx.userId,
 89			conversationKey: hashIdentity(conversationId),
 90			toolCallKey: hashIdentity(normalizedToolCallId),
 91		};
 92	}
 93	
 94	/** Remove live approval mutations before a historical result is persisted. */
 95	export function displaySafeMcpAppResult(value: unknown): unknown {
 96		if (!isRecord(value) || !Array.isArray(value.actions)) return value;
 97		return {
 98			...value,
 99			actions: value.actions.filter(
100				(action) => !isRecord(action) || action.tool !== "resolve_lobu_approval",
101			),
102		};
103	}
104	
105	/** Accept only small primitive interaction state; result data never flows here. */
106	export function boundedMcpAppViewState(value: unknown): McpAppViewState {
107		if (!isRecord(value)) return {};
108		const state: McpAppViewState = {};
109		for (const [key, inner] of Object.entries(value).slice(
110			0,
111			VIEW_STATE_MAX_KEYS,
112		)) {
113			if (!key || key.length > VIEW_STATE_KEY_MAX_LENGTH) continue;
114			if (
115				typeof inner !== "boolean" &&
116				!(typeof inner === "number" && Number.isFinite(inner)) &&
117				!(
118					typeof inner === "string" &&
119					inner.length <= VIEW_STATE_STRING_MAX_LENGTH
120				)
121			) {
122				continue;
123			}
124			const candidate = { ...state, [key]: inner as boolean | number | string };
125			if (
126				Buffer.byteLength(JSON.stringify(candidate), "utf8") >
127				VIEW_STATE_MAX_BYTES
128			)
129				break;
130			state[key] = inner as boolean | number | string;
131		}
132		return state;
133	}
134	
135	function parseSnapshot(body: string): SnapshotPayload | null {
136		try {
137			const parsed: unknown = JSON.parse(decrypt(body));
138			if (
139				!isRecord(parsed) ||
140				parsed.version !== 1 ||
141				typeof parsed.toolName !== "string" ||
142				!isRecord(parsed.data)
143			) {
144				return null;
145			}
146			return {
147				version: 1,
148				toolName: parsed.toolName,
149				data: parsed.data,
150				viewState: boundedMcpAppViewState(parsed.viewState),
151				...(typeof parsed.bindingKey === "string" &&
152				/^[a-f0-9]{64}$/.test(parsed.bindingKey)
153					? { bindingKey: parsed.bindingKey }
154					: {}),
155			};
156		} catch {
157			return null;
158		}
159	}
160	
161	function serializeSnapshot(payload: SnapshotPayload): {
162		body: string;
163		plaintextBytes: number;
164	} | null {
165		const plaintext = JSON.stringify(payload);
166		const plaintextBytes = Buffer.byteLength(plaintext, "utf8");
167		if (plaintextBytes === 0 || plaintextBytes > MCP_APP_RESULT_MAX_BYTES)
168			return null;
169		return { body: encrypt(plaintext), plaintextBytes };
170	}
171	
172	export async function storeMcpAppResultSnapshot(args: {
173		ctx: ToolContext;
174		toolCallId: unknown;
175		bindingCapability?: unknown;
176		toolName: string;
177		data: UnknownRecord;
178	}): Promise<boolean> {
179		const identity = snapshotIdentity(args.ctx, args.toolCallId);
180		if (
181			!identity ||
182			!args.toolName ||
183			args.toolName.length > TOOL_NAME_MAX_LENGTH
184		)
185			return false;
186		const bindingCapability = normalizeMcpAppToolCallId(args.bindingCapability);
187		const data = displaySafeMcpAppResult(args.data);
188		if (!isRecord(data)) return false;
189		const serialized = serializeSnapshot({
190			version: 1,
191			toolName: args.toolName,
192			data,
193			viewState: {},
194			...(bindingCapability
195				? { bindingKey: hashIdentity(bindingCapability) }
196				: {}),
197		});
198		if (!serialized) return false;
199	
200		const sql = getDb();
201		const collided = await sql.begin(async (tx) => {
202			const [stored] = await tx<{ collided: boolean }>`
203				INSERT INTO public.mcp_app_result_snapshots (
204					organization_id, client_id, user_id, conversation_key,
205					tool_call_key, tool_name, body, plaintext_bytes, expires_at
206				) VALUES (
207					${identity.organizationId}, ${identity.clientId}, ${identity.userId},
208					${identity.conversationKey}, ${identity.toolCallKey}, ${args.toolName},
209					${serialized.body}, ${serialized.plaintextBytes},
210					now() + (${MCP_APP_RESULT_RETENTION_DAYS} * interval '1 day')
211				)
212				ON CONFLICT (
213					organization_id, client_id, user_id, conversation_key, tool_call_key
214				) DO UPDATE SET
215					-- A host request ID is not guaranteed to be unique forever. Never let a
216					-- collision replace the historical card with a different result.
217					expires_at = now(),
218					updated_at = now()
219				RETURNING expires_at <= now() AS collided
220			`;
221			await tx`
222				DELETE FROM public.mcp_app_result_snapshots snapshot
223				WHERE snapshot.organization_id = ${identity.organizationId}
224					AND snapshot.client_id = ${identity.clientId}
225					AND snapshot.user_id = ${identity.userId}
226					AND snapshot.conversation_key = ${identity.conversationKey}
227					AND snapshot.tool_call_key NOT IN (
228						SELECT kept.tool_call_key
229						FROM public.mcp_app_result_snapshots kept
230						WHERE kept.organization_id = ${identity.organizationId}
231							AND kept.client_id = ${identity.clientId}
232							AND kept.user_id = ${identity.userId}
233							AND kept.conversation_key = ${identity.conversationKey}
234						ORDER BY kept.updated_at DESC, kept.tool_call_key
235						LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
236					)
237			`;
238			return stored?.collided === true;
239		});
240		if (collided) {
241			logger.warn(
242				{ toolName: args.toolName },
243				"MCP App result snapshot key collision; historical restore disabled",
244			);
245		}
246		return !collided;
247	}
