274	async function restoreMcpAppResultImpl(
275		args: {
276			tool_call_id?: string | number;
277			snapshot_capability?: string;
278			tool_name?: string;
279		},
280		_env: Env,
281		ctx: ToolContext,
282	) {
283		const sql = getDb();
284		const identity =
285			args.tool_call_id === undefined
286				? null
287				: snapshotIdentity(ctx, args.tool_call_id);
288		let row: SnapshotRow | undefined;
289		if (identity) {
290			[row] = await sql<SnapshotRow>`
291				SELECT body, tool_name
292				FROM public.mcp_app_result_snapshots
293				WHERE organization_id = ${identity.organizationId}
294					AND client_id = ${identity.clientId}
295					AND user_id = ${identity.userId}
296					AND conversation_key = ${identity.conversationKey}
297					AND tool_call_key = ${identity.toolCallKey}
298					AND expires_at > now()
299			`;
300		}
301	
302		const capabilityIdentity = snapshotIdentity(ctx, args.snapshot_capability);
303		if (!row && capabilityIdentity) {
304			const candidates = await sql<SnapshotLookupRow>`
305				SELECT body, tool_name, tool_call_key
306				FROM public.mcp_app_result_snapshots
307				WHERE organization_id = ${capabilityIdentity.organizationId}
308					AND client_id = ${capabilityIdentity.clientId}
309					AND user_id = ${capabilityIdentity.userId}
310					AND conversation_key = ${capabilityIdentity.conversationKey}
311					AND expires_at > now()
312				ORDER BY updated_at DESC, tool_call_key
313				LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
314			`;
315			row = candidates.find((candidate) => {
316				const snapshot = parseSnapshot(candidate.body);
317				return snapshot?.bindingKey === capabilityIdentity.toolCallKey;
318			});
319		}
320		if (!row || (args.tool_name && row.tool_name !== args.tool_name))
321			return { found: false, view_state: {} };
322		const snapshot = parseSnapshot(row.body);
323		if (!snapshot || snapshot.toolName !== row.tool_name) {
324			logger.warn(
325				{ toolName: row.tool_name },
326				"Discarded unreadable MCP App result snapshot",
327			);
328			return { found: false, view_state: {} };
329		}
330		return {
331			found: true,
332			tool_name: snapshot.toolName,
333			data: snapshot.data,
334			view_state: snapshot.viewState,
335		};
336	}
