364	async function saveMcpAppStateImpl(
365		args: {
366			tool_call_id?: string | number;
367			snapshot_capability?: string;
368			tool_name?: string;
369			view_state: UnknownRecord;
370		},
371		_env: Env,
372		ctx: ToolContext,
373	) {
374		const identity =
375			args.tool_call_id === undefined
376				? null
377				: snapshotIdentity(ctx, args.tool_call_id);
378		const viewState = boundedMcpAppViewState(args.view_state);
379		const sql = getDb();
380		const bindingIdentity = snapshotIdentity(
381			ctx,
382			// Some hosts preserve their own request metadata but intentionally strip
383			// app-supplied metadata. This private app-only argument keeps the one-time
384			// capability end to end; metadata remains supported for standard hosts.
385			args.snapshot_capability ?? ctx.mcpAppSnapshotCapability,
386		);
387		if (!identity && !bindingIdentity) return { saved: false };
388		if (!identity && bindingIdentity) {
389			try {
390				return await sql.begin(async (tx) => {
391					const candidates = await tx<SnapshotLookupRow>`
392						SELECT body, tool_name, tool_call_key
393						FROM public.mcp_app_result_snapshots
394						WHERE organization_id = ${bindingIdentity.organizationId}
395							AND client_id = ${bindingIdentity.clientId}
396							AND user_id = ${bindingIdentity.userId}
397							AND conversation_key = ${bindingIdentity.conversationKey}
398							AND expires_at > now()
399						ORDER BY updated_at DESC, tool_call_key
400						LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
401						FOR UPDATE
402					`;
403					const row = candidates.find((candidate) => {
404						const snapshot = parseSnapshot(candidate.body);
405						return snapshot?.bindingKey === bindingIdentity.toolCallKey;
406					});
407					if (!row || (args.tool_name && row.tool_name !== args.tool_name))
408						return { saved: false };
409					const snapshot = parseSnapshot(row.body);
410					if (!snapshot || snapshot.toolName !== row.tool_name)
411						return { saved: false };
412					const serialized = serializeSnapshot({ ...snapshot, viewState });
413					if (!serialized) return { saved: false };
414					const updated = await tx`
415						UPDATE public.mcp_app_result_snapshots
416						SET tool_call_key = ${bindingIdentity.toolCallKey},
417							body = ${serialized.body},
418							plaintext_bytes = ${serialized.plaintextBytes},
419							updated_at = now()
420						WHERE organization_id = ${bindingIdentity.organizationId}
421							AND client_id = ${bindingIdentity.clientId}
422							AND user_id = ${bindingIdentity.userId}
423							AND conversation_key = ${bindingIdentity.conversationKey}
424							AND tool_call_key = ${row.tool_call_key}
425					`;
426					return { saved: updated.count === 1 };
427				});
428			} catch (error) {
429				if (!isRecord(error) || error.code !== "23505") throw error;
430				logger.warn(
431					{ toolName: args.tool_name },
432					"MCP App capability key collision; candidate restore disabled",
433				);
434				return { saved: false };
435			}
436		}
437		if (!identity) return { saved: false };
438		if (bindingIdentity && bindingIdentity.toolCallKey !== identity.toolCallKey) {
439			try {
440				return await sql.begin(async (tx) => {
441					const [candidate] = await tx<SnapshotRow>`
442						SELECT body, tool_name
443						FROM public.mcp_app_result_snapshots
444						WHERE organization_id = ${bindingIdentity.organizationId}
445							AND client_id = ${bindingIdentity.clientId}
446							AND user_id = ${bindingIdentity.userId}
447							AND conversation_key = ${bindingIdentity.conversationKey}
448							AND tool_call_key = ${bindingIdentity.toolCallKey}
449							AND expires_at > now()
450						FOR UPDATE
451					`;
452					const row =
453						candidate ??
454						(
455							await tx<SnapshotRow>`
456								SELECT body, tool_name
457								FROM public.mcp_app_result_snapshots
458								WHERE organization_id = ${identity.organizationId}
459									AND client_id = ${identity.clientId}
460									AND user_id = ${identity.userId}
461									AND conversation_key = ${identity.conversationKey}
462									AND tool_call_key = ${identity.toolCallKey}
463									AND expires_at > now()
464							`
465						)[0];
466					if (!row) return { saved: false };
467					if (args.tool_name && row.tool_name !== args.tool_name)
468						return { saved: false };
469					const snapshot = parseSnapshot(row.body);
470					if (
471						!snapshot ||
472						snapshot.toolName !== row.tool_name ||
473						snapshot.bindingKey !== bindingIdentity.toolCallKey
474					)
475						return { saved: false };
476					const serialized = serializeSnapshot({ ...snapshot, viewState });
477					if (!serialized) return { saved: false };
478					const sourceIdentity = candidate ? bindingIdentity : identity;
479					const updated = await tx`
480						UPDATE public.mcp_app_result_snapshots
481						SET tool_call_key = ${identity.toolCallKey},
482							body = ${serialized.body},
483							plaintext_bytes = ${serialized.plaintextBytes},
484							updated_at = now()
485						WHERE organization_id = ${sourceIdentity.organizationId}
486							AND client_id = ${sourceIdentity.clientId}
487							AND user_id = ${sourceIdentity.userId}
488							AND conversation_key = ${sourceIdentity.conversationKey}
489							AND tool_call_key = ${sourceIdentity.toolCallKey}
490					`;
491					return { saved: updated.count === 1 };
492				});
493			} catch (error) {
494				if (!isRecord(error) || error.code !== "23505") throw error;
495				await sql`
496					UPDATE public.mcp_app_result_snapshots
497					SET expires_at = now(), updated_at = now()
498					WHERE organization_id = ${bindingIdentity.organizationId}
499						AND client_id = ${bindingIdentity.clientId}
500						AND user_id = ${bindingIdentity.userId}
501						AND conversation_key = ${bindingIdentity.conversationKey}
502						AND tool_call_key = ${bindingIdentity.toolCallKey}
503				`;
504				logger.warn(
505					{ toolName: args.tool_name },
506					"MCP App host card key collision; candidate restore disabled",
507				);
508				return { saved: false };
509			}
510		}
511		return sql.begin(async (tx) => {
512			const [row] = await tx<SnapshotRow>`
513				SELECT body, tool_name
514				FROM public.mcp_app_result_snapshots
515				WHERE organization_id = ${identity.organizationId}
516					AND client_id = ${identity.clientId}
517					AND user_id = ${identity.userId}
518					AND conversation_key = ${identity.conversationKey}
519					AND tool_call_key = ${identity.toolCallKey}
520					AND expires_at > now()
521				FOR UPDATE
522			`;
523			if (!row) return { saved: false };
524			if (args.tool_name && row.tool_name !== args.tool_name)
525				return { saved: false };
526			const snapshot = parseSnapshot(row.body);
527			if (!snapshot || snapshot.toolName !== row.tool_name)
528				return { saved: false };
529			const serialized = serializeSnapshot({ ...snapshot, viewState });
530			if (!serialized) return { saved: false };
531			await tx`
532				UPDATE public.mcp_app_result_snapshots
533				SET body = ${serialized.body},
534					plaintext_bytes = ${serialized.plaintextBytes},
535					updated_at = now()
536				WHERE organization_id = ${identity.organizationId}
537					AND client_id = ${identity.clientId}
538					AND user_id = ${identity.userId}
539					AND conversation_key = ${identity.conversationKey}
540					AND tool_call_key = ${identity.toolCallKey}
541			`;
542			return { saved: true };
543		});
544	}
