     1	/**
     2	 * Post-build tripwire for MCP Apps.
     3	 *
     4	 * The current MCP Apps resource is a packed, self-contained HTML document so
     5	 * it does not depend on cross-origin script execution inside a host sandbox.
     6	 * We also keep a small external template for Lobu's own public app route. Its
     7	 * stable assets use content-derived query versions for rolling deployments.
     8	 */
     9	import { createHash } from "node:crypto";
    10	import { readdir, readFile, stat } from "node:fs/promises";
    11	
    12	const MAX_RESOURCE_RESPONSE_BYTES = 450_000;
    13	const APP_ORIGIN = "https://app.lobu.ai";
    14	const APP_BASE = `${APP_ORIGIN}/mcp-apps/interaction/`;
    15	const bundleUrl = new URL(
    16		"../dist-mcp-apps/interaction/index.html",
    17		import.meta.url,
    18	);
    19	const source = await readFile(bundleUrl, "utf8");
    20	const legacySource = await readFile(
    21		new URL("../dist-mcp-apps/interaction/legacy-v2.html", import.meta.url),
    22		"utf8",
    23	);
    24	const currentResourceSource = legacySource;
    25	const assetsUrl = new URL(
    26		"../dist-mcp-apps/interaction/assets/",
    27		import.meta.url,
    28	);
    29	const allAssetPaths = (await readdir(assetsUrl))
    30		.map((name) => `assets/${name}`)
    31		.sort();
    32	const renderedSource = source
    33		.replace("<head>", `<head><base href="${APP_BASE}">`)
    34		.replaceAll("__LOBU_MCP_APP_ORIGIN__", APP_ORIGIN);
    35	const sourceBytes = Buffer.byteLength(renderedSource, "utf8");
    36	const assetPaths = [
    37		...source.matchAll(/(?:src|href)="\.\/(assets\/[^"?#]+)(?:\?v=[^"]+)?"/g),
    38	].map((match) => match[1]);
    39	const versionedAssetReferences = [
    40		...source.matchAll(/(?:src|href)="\.\/(assets\/[^"?#]+)\?v=([a-f0-9]{16})"/g),
    41	].map((match) => ({ assetPath: match[1], version: match[2] }));
    42	const cssPaths = assetPaths.filter((assetPath) => assetPath.endsWith(".css"));
    43	const scriptPaths = assetPaths.filter((assetPath) => assetPath.endsWith(".js"));
    44	const resourceResponseBytes = Buffer.byteLength(
    45		JSON.stringify({
    46			jsonrpc: "2.0",
    47			id: 1,
    48			result: {
    49				contents: [
    50					{
    51						uri: "ui://lobu/interaction/v11.html",
    52						mimeType: "text/html;profile=mcp-app",
    53						text: currentResourceSource,
    54						_meta: {
    55							ui: {
    56								csp: {
    57									connectDomains: [],
    58									resourceDomains: [],
    59									frameDomains: [],
    60									baseUriDomains: [],
    61								},
    62								permissions: { clipboardWrite: {} },
    63								prefersBorder: true,
    64							},
    65						},
    66					},
    67				],
    68			},
    69		}),
    70		"utf8",
    71	);
    72	const requiredStoredTemplateSelectors = [
    73		".space-y-3",
    74		".gap-4",
    75		".pr-4",
    76		".pt-6",
    77		".grid-cols-\\[repeat\\(auto-fill\\,minmax\\(200px\\,1fr\\)\\)\\]",
    78	];
    79	
    80	const errors = [];
    81	if (
    82		!legacySource.includes('name="lobu-mcp-packing"') ||
    83		!legacySource.includes("gzip-base64-self-contained") ||
    84		!legacySource.includes("DecompressionStream") ||
    85		!legacySource.includes("pako.ungzip")
    86	) {
    87		errors.push("self-contained MCP App template is incomplete");
    88	}
    89	if (
    90		legacySource.includes("__LOBU_MCP_APP_ORIGIN__") ||
    91		/(?:src|href)=["'](?:\.\/|\/)?assets\//.test(legacySource)
    92	) {
    93		errors.push("legacy v2 template still depends on external assets");
    94	}
    95	if (!source.includes("__LOBU_MCP_APP_ORIGIN__")) {
    96		errors.push("dynamic MCP App origin placeholder is missing");
    97	}
    98	if (!renderedSource.includes(`<base href="${APP_BASE}">`)) {
    99		errors.push("absolute MCP App asset base is missing");
   100	}
   101	if (!renderedSource.includes('http-equiv="Content-Security-Policy"')) {
   102		errors.push("defense-in-depth Content Security Policy is missing");
   103	}
   104	if (source.includes("<script>") || source.includes("<style>")) {
   105		errors.push("inline JS/CSS remains in the MCP App snapshot template");
   106	}
   107	if (
   108		!/<script defer src="\.\/assets\/app\.js\?v=[a-f0-9]{16}"><\/script>/.test(
   109			source,
   110		) ||
   111		/<script[^>]+type="module"/.test(source)
   112	) {
   113		errors.push(
   114			"external MCP App template is not using one classic deferred script",
   115		);
   116	}
   117	if (scriptPaths.length !== 1 || cssPaths.length !== 1) {
   118		errors.push(
   119			`expected one external JS and one external CSS asset; found ${scriptPaths.length} JS and ${cssPaths.length} CSS`,
   120		);
   121	}
   122	const expectedAssetPaths = ["assets/app.css", "assets/app.js"];
   123	if (JSON.stringify(allAssetPaths) !== JSON.stringify(expectedAssetPaths)) {
   124		errors.push(
   125			`expected only stable MCP App assets ${expectedAssetPaths.join(", ")}; found ${allAssetPaths.join(", ")}`,
   126		);
   127	}
   128	if (
   129		JSON.stringify(
   130			versionedAssetReferences.map(({ assetPath }) => assetPath).sort(),
   131		) !== JSON.stringify(expectedAssetPaths)
   132	) {
   133		errors.push("stable MCP App asset URLs are missing content-derived versions");
   134	}
   135	if (resourceResponseBytes > MAX_RESOURCE_RESPONSE_BYTES) {
   136		errors.push(
   137			`resources/read JSON is ${resourceResponseBytes.toLocaleString()} bytes; budget is ${MAX_RESOURCE_RESPONSE_BYTES.toLocaleString()} bytes`,
   138		);
   139	}
   140	
   141	let css = "";
   142	let javascript = "";
   143	for (const assetPath of allAssetPaths) {
   144		const assetUrl = new URL(
   145			`../dist-mcp-apps/interaction/${assetPath}`,
   146			import.meta.url,
   147		);
   148		try {
   149			await stat(assetUrl);
   150			const asset = await readFile(assetUrl);
   151			const expectedVersion = createHash("sha256")
   152				.update(asset)
   153				.digest("hex")
   154				.slice(0, 16);
   155			const reference = versionedAssetReferences.find(
   156				(candidate) => candidate.assetPath === assetPath,
   157			);
   158			if (reference?.version !== expectedVersion) {
   159				errors.push(`MCP App asset version does not match ${assetPath} contents`);
   160			}
   161			if (assetPath.endsWith(".css")) css += asset.toString("utf8");
   162			if (assetPath.endsWith(".js")) javascript += asset.toString("utf8");
   163		} catch {
   164			errors.push(`referenced MCP App asset is missing: ${assetPath}`);
   165		}
   166	}
   167	try {
   168		// Compilation as a classic script rejects module-only syntax such as
   169		// import.meta, top-level imports/exports, and top-level await.
   170		new Function(javascript);
   171	} catch (error) {
   172		errors.push(
   173			`external MCP App JavaScript is not classic-script compatible: ${error}`,
   174		);
   175	}
   176	if (
   177		css.includes("/fonts/") ||
   178		/url\(\s*(["']?)(?!data:|#)[^)]+\1\s*\)/i.test(css)
   179	) {
   180		errors.push("unexpected runtime URL remains in MCP App CSS");
   181	}
   182	for (const selector of requiredStoredTemplateSelectors) {
   183		if (!css.includes(selector)) {
   184			errors.push(
   185				`stored json_template utility is missing from CSS: ${selector}`,
   186			);
   187		}
   188	}
   189	
   190	if (errors.length > 0) {
   191		console.error("MCP App bundle check FAILED:\n");
   192		for (const error of errors) console.error(`• ${error}`);
   193		process.exitCode = 1;
   194	} else {
   195		console.log(
   196			`MCP App bundle check passed (${sourceBytes.toLocaleString()} external HTML bytes; ${resourceResponseBytes.toLocaleString()} v11 self-contained resources/read JSON bytes; ${Buffer.byteLength(legacySource).toLocaleString()} packed HTML bytes; classic content-versioned app.js/app.css).`,
   197		);
   198	}
